<?php declare(strict_types=1); /** @var Closure(mixed):string $escape */ $money=static fn(float$v):string=>'R$ '.number_format($v,2,',','.');$statusNames=['ACTIVE'=>'Ativa','INACTIVE'=>'Pausada','EXPIRED'=>'Encerrada'];$cycleNames=['WEEKLY'=>'Semanal','BIWEEKLY'=>'Quinzenal','MONTHLY'=>'Mensal','BIMONTHLY'=>'Bimestral','QUARTERLY'=>'Trimestral','SEMIANNUALLY'=>'Semestral','YEARLY'=>'Anual'];$billingNames=['PIX'=>'Pix','BOLETO'=>'Boleto','CREDIT_CARD'=>'Cartão'];$query=static fn(array$changes):string=>http_build_query(array_filter(array_merge(['q'=>$search,'status'=>$statusFilter,'cycle'=>$cycleFilter],$changes),static fn($v):bool=>$v!==''));$first=$result['total']===0?0:(($result['page']-1)*50)+1;$last=min($result['total'],$result['page']*50); ?>
<nav class="finance-section-tabs"><a href="<?= $escape($basePath) ?>/finance/payments">Cobranças</a><a class="active" href="<?= $escape($basePath) ?>/finance/subscriptions">Assinaturas</a></nav>
<div class="finance-customer-heading"><div><span class="status">Financeiro</span><h1>Assinaturas</h1><p class="meta">Gerencie mensalidades e cobranças recorrentes das unidades permitidas.</p></div><a class="button-primary" href="<?= $escape($basePath) ?>/finance/customers"><i class="fa-solid fa-plus"></i> Nova assinatura</a></div>
<div class="dashboard-grid mb-4"><article class="metric-card"><span>Ativas</span><strong><?= number_format((int)$result['summary']['active'],0,',','.') ?></strong></article><article class="metric-card"><span>Pausadas</span><strong><?= number_format((int)$result['summary']['inactive'],0,',','.') ?></strong></article><article class="metric-card"><span>Recorrência mensal ativa</span><strong><?= $escape($money((float)$result['summary']['monthly_value'])) ?></strong></article></div>
<section class="finance-customer-toolbar"><form method="get" action="<?= $escape($basePath) ?>/finance/subscriptions"><div class="finance-search-row"><label class="finance-search-box"><i class="fa-solid fa-magnifying-glass"></i><input name="q" value="<?= $escape($search) ?>" placeholder="Cliente, CPF/CNPJ, descrição ou ID da assinatura"></label><button class="button-primary finance-search-button" type="submit">Pesquisar</button><details class="finance-filter-panel"<?= ($statusFilter!==''||$cycleFilter!=='')?' open':'' ?>><summary><i class="fa-solid fa-filter"></i> Filtros</summary><div class="finance-filter-content"><label>Situação<select name="status"><option value="">Todas</option><?php foreach(['ACTIVE'=>'Ativa','INACTIVE'=>'Pausada','EXPIRED'=>'Encerrada']as$value=>$label):?><option value="<?= $value ?>"<?= $statusFilter===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><label>Periodicidade<select name="cycle"><option value="">Todas</option><?php foreach($cycleNames as$value=>$label):?><option value="<?= $value ?>"<?= $cycleFilter===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><div class="finance-filter-actions"><button class="button-primary" type="submit">Aplicar</button><a class="button-secondary" href="<?= $escape($basePath) ?>/finance/subscriptions">Limpar</a></div></div></details></div></form></section>
<div class="finance-result-bar"><span>Exibindo <strong><?= $first ?>–<?= $last ?></strong> de <?= number_format((int)$result['total'],0,',','.') ?></span><span><i class="fa-solid fa-shield-halved"></i> Dados conforme suas permissões</span></div>
<div class="table-responsive finance-customer-table"><table><thead><tr><th>Cliente</th><th>Descrição</th><th>Unidade</th><th>Forma</th><th>Recorrência</th><th>Valor</th><th>Próximo vencimento</th><th>Situação</th></tr></thead><tbody><?php if($result['items']===[]):?><tr><td colspan="8"><div class="finance-empty"><i class="fa-solid fa-arrows-rotate"></i><strong>Nenhuma assinatura encontrada</strong><span>Crie uma assinatura pela ficha de um cliente conciliado.</span></div></td></tr><?php endif;?><?php foreach($result['items']as$item):?><tr><td><a href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$item['finance_customer_id'] ?>"><strong><?= $escape($item['customer_name']) ?></strong></a></td><td><?= $escape($item['description']) ?></td><td><?= $escape($item['unit_name']) ?></td><td><?= $escape($billingNames[$item['billing_type']]??$item['billing_type']) ?></td><td><?= $escape($cycleNames[$item['cycle']]??$item['cycle']) ?></td><td><strong><?= $escape($money((float)$item['value'])) ?></strong></td><td><?= $escape(date('d/m/Y',strtotime($item['next_due_date']))) ?></td><td><span class="connection-badge"><?= $escape($statusNames[$item['status']]??$item['status']) ?></span></td></tr><?php endforeach;?></tbody></table></div>
<?php if($result['pages']>1):?><nav class="finance-pagination"><span>Página <?= (int)$result['page'] ?> de <?= (int)$result['pages'] ?></span><div><?php if($result['page']>1):?><a href="?<?= $escape($query(['page'=>$result['page']-1])) ?>"><i class="fa-solid fa-chevron-left"></i></a><?php endif;?><span><?= (int)$result['page'] ?></span><?php if($result['page']<$result['pages']):?><a href="?<?= $escape($query(['page'=>$result['page']+1])) ?>"><i class="fa-solid fa-chevron-right"></i></a><?php endif;?></div></nav><?php endif;?>
